{
  "type": "json_object",
  "message": "The requested change is the 2006 year-end reserve for product warranties minus the 2005 year-end reserve. The product warranties note states the reserve was $10 million at Dec. 31, 2006 and $4 million at Dec. 31, 2005, both in USD millions. I compute 10 - 4.",
  "tool": "calculate",
  "arguments": {
    "expression": "reserve_2006 - reserve_2005",
    "variables": {
      "reserve_2006": {
        "value": 10,
        "source": "source:q11n3",
        "unit": "USD_million"
      },
      "reserve_2005": {
        "value": 4,
        "source": "source:q11n4",
        "unit": "USD_million"
      }
    },
    "sources": {
      "reserve_2006": "source:q11n3",
      "reserve_2005": "source:q11n4"
    }
  }
}
